from lib import *
S = SS('x100')
steps = [
    step("序列化器。自动配置的 RedisTemplate 的 key 和 value 序列化器都是 JdkSerializationRedisSerializer,StringRedisTemplate 的则是 StringRedisSerializer。同样存一个 User(alice,30,两个 tag):用默认 RedisTemplate 存到 redis 里,key 变成 b'\\xac\\xed\\x00\\x05t\\x00\\x08jdk:user'(前面多了 JDK 序列化的头),value 共 161 字节,里面带着类名 demo.User;用 Jackson 序列化器(GenericJacksonJsonRedisSerializer)存,key 是普通的 json:user,value 共 42 字节,内容是 {\"age\":30,\"name\":\"alice\",\"tags\":[\"a\",\"b\"]};StringRedisTemplate 存的 str:name 值就是 5 个字节的 alice。JDK 方式的 key 在 redis-cli 和其他语言的客户端里读不出来、找不到,value 也比 JSON 大近 4 倍(161 对 42,算出来的比值);读回来时 JDK 方式还原成 User,Jackson 方式用泛型序列化器读回来的是一个 Map({age=30, name=alice, tags=[a, b]})——因为我这里没有在 JSON 里保存类型信息。", t=tl(S(1)), mark=lidx(S(1), "b'\\xac\\xed", '读回来'), done=lidx(S(1), '自动配置的 RedisTemplate', 'json:user', 'str:name'), b=bars([['JDK 序列化的 value 字节数', 161, '161'], ['Jackson JSON 的 value 字节数', 42, '42'], ['StringRedisTemplate 的 value 字节数', 5, '5']], 161, mark=[0], done=[1, 2]), kv=KV([['默认 RedisTemplate', 'key 和 value 都是 JDK 序列化,key 前面带 \\xac\\xed 头'], ['JSON 序列化器', 'key 可读,value 42 字节,其他语言能读'], ['StringRedisTemplate', '键值都是字符串'], ['泛型 JSON 读回', '没有类型信息时读回来是 Map']], ['默认 RedisTemplate'])),
    step("Lettuce 的连接(应用在跑时,监控用的连接先断开,connected_clients 里只有应用自己的)。classpath 上没有 commons-pool2(默认):64 个线程并发 GET 3 秒,共 286436 次(约 95479 次/秒),空闲时与压测中间的 connected_clients 都是 1——所有线程共用一个连接。classpath 上有 commons-pool2 时 Boot 自动启用连接池(是否用连接池:true),结果还是 1 个连接、95277 次/秒;再显式设 pool.enabled=false:连接池关掉,仍是 1 个连接。要真的用上池,还要把 shareNativeConnection 关掉(每次操作都从池里借连接,max-active=8):压测中间 connected_clients = 8,吞吐反而降到 54450 次/秒。Lettuce 默认的命令超时 PT1M,连接超时 PT10S。也就是说默认的单连接复用已经很高效,开连接池要么无效、要么更慢,除非用了阻塞命令或事务。", t=tl(S(2)), mark=lidx(S(2), '把 shareNativeConnection 关掉', 'commons-pool2(Boot 因此自动启用连接池)'), done=lidx(S(2), '没有 commons-pool2(默认)', 'pool.enabled 显式设成 false'), b=bars([['默认:压测中间 connected_clients', 1, '1'], ['默认:吞吐(次/秒)', 95479, '95479'], ['关掉 shareNativeConnection:connected_clients', 8, '8'], ['关掉 shareNativeConnection:吞吐(次/秒)', 54450, '54450']], 95479, done=[0, 1], mark=[2, 3]), kv=KV([['默认', '64 个线程共用 1 个连接,约 95000 次/秒'], ['classpath 有 commons-pool2', '自动启用连接池,但共享连接,仍是 1 个'], ['不共享连接 + 池', '8 个连接,吞吐降到约 54000 次/秒'], ['默认超时', '命令超时 1 分钟,连接超时 10 秒']], ['默认'])),
    step("pipeline。往 Redis 写 10000 个 key,各取 3 次中位数。循环里一个一个 opsForValue().set:中位 461 ms(范围 378 到 624)。executePipelined(把 10000 条 SET 放进一个 pipeline):中位 67 ms(60 到 121),约快了 7 倍(算出来的比值)。multiSet(一条 MSET):中位 10 ms(8 到 12)。三种做法写进去的结果一样(dbsize 都是 10000)。往返次数从 10000 次降到 1 次是最大的收益;能用 MSET 这类原生批量命令时更省,pipeline 适合不能合并成一条命令的一批命令。", t=tl(S(3)), mark=lidx(S(3), '循环里一个一个 set'), done=lidx(S(3), 'executePipelined', 'multiSet'), b=bars([['循环 set(ms)', 461, '461'], ['executePipelined(ms)', 67, '67'], ['multiSet(ms)', 10, '10']], 461, mark=[0], done=[1, 2]), kv=KV([['循环', '10000 次往返,461 ms'], ['pipeline', '一批发出,67 ms'], ['MSET', '一条命令,10 ms'], ['结果', '三种都是 10000 个 key']], ['pipeline'])),
    step("Redis 不可用时。指向没有 Redis 的端口:第一条命令失败,最里面的异常是 java.net.ConnectException: Connection refused。更有意思的是运行中 Redis 被 kill -9(第 2.5 秒),第 7.5 秒再启动,spring.data.redis.timeout=2s,应用每 0.5 秒 GET 一次:Redis 活着时每次 1 到 3 ms(第一次 233 ms,含建连);Redis 被杀之后,GET 并不是立刻失败,而是等满超时才失败——t=4.8s、7.3s、9.8s 三次都是 QueryTimeoutException / RedisCommandTimeoutException,用时 2006 ms、2005 ms、2005 ms;Redis 在第 7.5 秒起来之后,第一次成功要到 t=11.7s,这次花了 1413 ms(重新建连),之后又是 1 ms。这就是说宕机期间每个调用方都会被卡满超时时间;默认的命令超时是 1 分钟,线程可能被拖住很久,生产里要把 spring.data.redis.timeout 调小,并配上熔断或降级。", t=tl(S(4)), mark=lidx(S(4), 't= 4.8s', 't= 7.3s', 't= 9.8s', 't=11.7s'), done=lidx(S(4), '端口上没有 Redis', 't= 0.2s', 't= 2.3s'), b=bars([['Redis 活着时的 GET(ms)', 1, '1'], ['Redis 宕机时的 GET 失败前等待(ms)', 2005, '2005'], ['恢复后第一次成功 GET(ms)', 1413, '1413']], 2005, done=[0], mark=[1, 2]), kv=KV([['没有 Redis 的端口', 'ConnectException: Connection refused'], ['运行中 Redis 宕机', '每个 GET 等满 2 秒(设置的超时)才失败'], ['恢复', '第一次成功 GET 用了 1413 ms(重连)'], ['默认', '命令超时 1 分钟,要调小']], ['运行中 Redis 宕机'])),
]
A = mkartx('x100', 100, 'Spring,Data,Redis,Lettuce,序列化,pipeline,真实验证,动画演示',
    '实测 Spring Data Redis 4 与 Lettuce:默认 RedisTemplate 用 JDK 序列化,key 前面带 \\xac\\xed 头、value 161 字节而 JSON 只要 42 字节;64 个线程共用 1 个 Lettuce 连接约 95000 次/秒,开连接池要关掉共享连接才会起作用且更慢;10000 个 SET 循环 461 ms、pipeline 67 ms、MSET 10 ms;Redis 宕机时每个命令等满超时才失败,恢复后重连一次 1413 ms。',
    'RedisTemplate 存进去的 key 为什么是乱码?Lettuce 要不要配连接池?pipeline 到底快多少?Redis 挂了应用会怎样?这篇在 Spring Boot 4.0.8、Spring Data Redis 4、Lettuce 上用自己起的 Redis 逐个实测。',
    [('161 vs 42 字节', '同一个 User 对象,JDK 序列化与 Jackson JSON 在 Redis 里的 value 大小'), ('461 → 67 → 10 ms', '写 10000 个 key:循环 set、executePipelined、multiSet 的中位耗时'), ('2005 ms', 'Redis 宕机期间,超时设为 2 秒时每个 GET 失败前的等待时间')],
    [('序列化器', '<p>默认 RedisTemplate 用 JDK 序列化:key 带头、value 大、其他语言读不了;StringRedisTemplate 与 JSON 序列化器是可读的。</p>'),
     ('Lettuce 的连接', '<p>默认所有线程共用一个连接;有 commons-pool2 也不一定真的用池;不共享连接的池反而更慢。</p>'),
     ('pipeline', '<p>往返次数是主要代价:循环 461 ms,pipeline 67 ms,MSET 10 ms。</p>'),
     ('Redis 不可用', '<p>运行中宕机时每个命令等满超时才失败,恢复后重连会让第一次调用变慢。</p>')],
    steps,
    [ENV_X + '(Spring Data Redis 4.0.7、Lettuce 6.8.2、Jackson 3;Redis 8.10.2 是本机自己起的实例,端口 7390,不碰用户自己的 6379)。序列化器对比存同一个 User;连接数取自应用内 INFO clients 的 connected_clients(运行期间我的监控连接先断开);吞吐是 64 个线程循环 GET 3 秒;pipeline 每种写法 3 次取中位数;宕机实验用 kill -9 杀掉 Redis 进程再启动',
     '没有验证:Redis Cluster 与 Sentinel 下的拓扑刷新与故障转移;SSL / 认证;Lettuce 的 ClientOptions 与断线重连策略(disconnectedBehavior 等)的具体取值;ReactiveRedisTemplate;发布订阅与 Stream;Redisson 的对比;value 带类型信息(activateDefaultTyping)的 JSON 序列化器的行为;大 value 与序列化耗时'],
    'Spring Data Redis')
